  /// 将包含简体中文汉字的文本转换为对应的日文汉字 (新字体)。
  ///
  /// 若文本中不含需要转换的汉字, 则原样返回。
  static String toJapaneseKanji(String text) {
    if (text.isEmpty) return text;

    var result = text;
    // 1. 优先替换常见歧义多字词
    for (final entry in _phraseOverrides.entries) {
      if (result.contains(entry.key)) {
        result = result.replaceAll(entry.key, entry.value);
      }
    }

    // 2. 逐字替换单字 (使用 runes 保证增补平面代理对字符不被劈开)
    final buffer = StringBuffer();
    for (final rune in result.runes) {
      final char = String.fromCharCode(rune);
      buffer.write(_charMap[char] ?? char);
    }
    return buffer.toString();
  }

  /// 判断文本中是否包含可转换为日文汉字的简体字。
  static bool hasSimplified(String text) {
    if (text.isEmpty) return false;
    for (final phrase in _phraseOverrides.keys) {
      if (text.contains(phrase)) return true;
    }
    for (final rune in text.runes) {
      final char = String.fromCharCode(rune);
      if (_charMap.containsKey(char)) return true;
    }
    return false;
  }
